func testMetaDatumToManyAddOpMetaDataIdAliases(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a MetaDatum
	var b, c, d, e Alias

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, metaDatumDBTypes, false, strmangle.SetComplement(metaDatumPrimaryKeyColumns, metaDatumColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*Alias{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, aliasDBTypes, false, strmangle.SetComplement(aliasPrimaryKeyColumns, aliasColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*Alias{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddMetaDataIdAliases(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if !queries.Equal(a.ID, first.MetaDataId) {
			t.Error("foreign key was wrong value", a.ID, first.MetaDataId)
		}
		if !queries.Equal(a.ID, second.MetaDataId) {
			t.Error("foreign key was wrong value", a.ID, second.MetaDataId)
		}

		if first.R.MetaDataIdMetaDatum != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.MetaDataIdMetaDatum != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.MetaDataIdAliases[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.MetaDataIdAliases[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.MetaDataIdAliases().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}

